-- Hand-edited: an order is a permanent record (ADR-0107 결정 1 #177 7항 '주문·체결 이력 보존';
-- #119 수용 기준), whoever writes. The intake inserts it in its final state; while it rests (대기,
-- 부분 체결) its fills, a cancel (#178) or the expiry (#120) update it in place, and that is all: its
-- terms — the owner, the market, the contract, the limits as sent and as protected, the reference
-- and the width, the size, the request id, the arrival key, the intake's instant — and a budget
-- order's outcome never change, the filled contracts and Coin never go down, the status only moves
-- forward to 부분 체결, 전량 체결, 취소 완료 or 만료, and an ended order never changes again. With
-- the rows' CHECKs (each state's reasons and end), the row and its fills are the order's history:
-- no events table. DELETE is refused (and REVOKEd below). TRUNCATE fires no row trigger: a wipe
-- (docs/RESET.md) still empties the table.
CREATE FUNCTION orders_keep_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'order % is a permanent record and takes no DELETE', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF OLD.status NOT IN ('open', 'partially_filled') THEN
    RAISE EXCEPTION 'order % ended as %: an ended order never changes', OLD.id, OLD.status
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF (NEW.id, NEW.user_id, NEW.market_id, NEW.outcome, NEW.side, NEW.time_in_force,
      NEW.limit_price, NEW.protected_limit_price, NEW.reference_price, NEW.protection_ticks,
      NEW.qty, NEW.budget_coin, NEW.unspent_coin, NEW.reject_reason, NEW.idempotency_key,
      NEW.arrival_seq, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.user_id, OLD.market_id, OLD.outcome, OLD.side, OLD.time_in_force,
      OLD.limit_price, OLD.protected_limit_price, OLD.reference_price, OLD.protection_ticks,
      OLD.qty, OLD.budget_coin, OLD.unspent_coin, OLD.reject_reason, OLD.idempotency_key,
      OLD.arrival_seq, OLD.created_at) THEN
    RAISE EXCEPTION 'order %: its terms never change', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.filled_qty < OLD.filled_qty OR NEW.filled_amount_coin < OLD.filled_amount_coin THEN
    RAISE EXCEPTION 'order %: what it filled never goes down', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.status NOT IN ('partially_filled', 'filled', 'cancelled', 'expired') THEN
    RAISE EXCEPTION 'order % moves from % to %: a resting order only moves forward', OLD.id,
      OLD.status, NEW.status
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER orders_keep_record
  BEFORE UPDATE OR DELETE ON "orders"
  FOR EACH ROW EXECUTE FUNCTION orders_keep_record();--> statement-breakpoint
REVOKE DELETE ON TABLE "orders" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: an account that holds the admin role takes no order, in any market, for as long as
-- it holds the role (ADR-0107 결정 5 '#119·#143 관리자의 거래', ADR-0093 #173 15항): the intake
-- refuses it with FORBIDDEN before anything is written (the role read with the owner's own profile
-- row FOR SHARE under the market's lock, which a grant's UPDATE of that row conflicts with — no
-- admin-roles lock, ADR-0112 10-16), and this refuses any other writer. The 운영 마켓메이커 has no
-- profile and passes; an order an account placed before it became an admin stays (#143 ends it).
CREATE FUNCTION orders_refuse_admin_owner() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM profiles p WHERE p.user_id = NEW.user_id AND p.role = 'admin') THEN
    RAISE EXCEPTION 'account % holds the admin role: it takes no order', NEW.user_id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER orders_refuse_admin_owner
  BEFORE INSERT ON "orders"
  FOR EACH ROW EXECUTE FUNCTION orders_refuse_admin_owner();--> statement-breakpoint
-- Hand-edited: a fill is one match the two orders it names allow (ADR-0111 결정 1·3·4·5, ADR-0107
-- 결정 1 #177 2·4·5·11항), whoever writes. Both orders are of the fill's market and owned by its
-- two owners, whose account types it copies as they are; the incoming order's contract is the
-- fill's and the price is within its protected limit; the resting order is a live GTC order that
-- arrived before it and still has the quantity; a trade meets the same outcome on the other side
-- at the resting price, a pair mint the other outcome's buy at the payout minus it; and the two
-- owners are not one self-trade group (`fills_orders_check` holds that they differ; two accounts
-- that are not a person's are one bundle, `is_human_account_type`). Read by primary key: every
-- writer of either table holds the market's lock (`lockMarket`), so neither order changes under
-- it. The orders' own fill totals are the writer's (the order's CHECKs bound them).
CREATE FUNCTION fills_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  incoming orders%ROWTYPE;
  resting orders%ROWTYPE;
BEGIN
  SELECT * INTO incoming FROM orders o WHERE o.id = NEW.incoming_order_id;
  SELECT * INTO resting FROM orders o WHERE o.id = NEW.resting_order_id;
  IF incoming.id IS NULL OR resting.id IS NULL
     OR incoming.market_id <> NEW.market_id OR resting.market_id <> NEW.market_id
     OR incoming.user_id <> NEW.incoming_owner_id OR resting.user_id <> NEW.resting_owner_id THEN
    RAISE EXCEPTION 'a fill names two orders of its market and their owners'
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.incoming_account_type IS DISTINCT FROM
       (SELECT u.account_type FROM "user" u WHERE u.id = NEW.incoming_owner_id)
     OR NEW.resting_account_type IS DISTINCT FROM
       (SELECT u.account_type FROM "user" u WHERE u.id = NEW.resting_owner_id) THEN
    RAISE EXCEPTION 'a fill records its owners'' account types as they are'
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NOT is_human_account_type(NEW.incoming_account_type)
     AND NOT is_human_account_type(NEW.resting_account_type) THEN
    RAISE EXCEPTION 'a fill never meets two accounts of one self-trade group'
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF incoming.outcome <> NEW.outcome OR incoming.side <> NEW.side
     OR (NEW.side = 'buy' AND NEW.price_coin > incoming.protected_limit_price)
     OR (NEW.side = 'sell' AND NEW.price_coin < incoming.protected_limit_price) THEN
    RAISE EXCEPTION 'a fill is the incoming order''s contract within its protected limit'
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF resting.status NOT IN ('open', 'partially_filled') OR resting.time_in_force <> 'gtc'
     OR resting.qty - resting.filled_qty < NEW.qty
     OR resting.arrival_seq >= incoming.arrival_seq THEN
    RAISE EXCEPTION 'a fill meets a resting order that is live, arrived before and still has %',
      NEW.qty
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NOT (CASE NEW.kind
       WHEN 'trade' THEN resting.outcome = NEW.outcome AND resting.side <> NEW.side
         AND NEW.price_coin = resting.protected_limit_price
       ELSE resting.outcome <> NEW.outcome AND resting.side = 'buy'
         AND NEW.price_coin = 100 - resting.protected_limit_price
     END) THEN
    RAISE EXCEPTION 'a % fill meets the resting order its kind meets, at its price', NEW.kind
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER fills_check
  BEFORE INSERT ON "fills"
  FOR EACH ROW EXECUTE FUNCTION fills_check();--> statement-breakpoint
-- Hand-edited: a fill is a permanent fact (#177 11항: every recorded fill is valid), whoever
-- writes; buddha_app loses UPDATE and DELETE below. TRUNCATE fires no row trigger.
CREATE FUNCTION fills_keep_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  RAISE EXCEPTION 'fill % is a permanent record and takes no %', OLD.id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER fills_keep_record
  BEFORE UPDATE OR DELETE ON "fills"
  FOR EACH ROW EXECUTE FUNCTION fills_keep_record();--> statement-breakpoint
REVOKE UPDATE, DELETE ON TABLE "fills" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: a fill's ledger events are its own (ADR-0110 결과 5, ADR-0109 결과 5 — GUARDS.md
-- '검사하지 않는 것' until now). A TRADE_FILL or PAIR_MINT_COLLATERAL refers to an existing fill (ref
-- `fill`, the id; its key the id, or the id and the leg's outcome) of its kind and market, and
-- moves that fill's Coin between that fill's owners' holders — a person's user ledger account, the
-- 운영 마켓메이커's funds of that market: a trade the buyer's price × qty to the seller; a pair
-- mint each buyer's leg price × qty into the market's collateral, the YES leg by the YES buyer.
-- With the unique key per type, each fill moves its Coin once. A comparison with a missing side
-- refuses (coalesce). Apart from 0060's `ledger_entries_check`, so that one keeps its body, and
-- named to fire after it (BEFORE triggers fire by name): an event its pair, market or totals
-- refuse is refused for that first.
CREATE FUNCTION ledger_entries_fill_binding() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  f fills%ROWTYPE;
  from_kind text;
  from_owner text;
  from_market uuid;
  to_kind text;
  to_owner text;
  to_market uuid;
  payer text;
  payee text;
  leg text;
  amount bigint;
BEGIN
  IF NEW.ref_type = 'fill' AND NEW.ref_id ~ '^[1-9][0-9]{0,17}$' THEN
    SELECT * INTO f FROM fills x WHERE x.id = NEW.ref_id::bigint;
  END IF;
  IF f.id IS NULL THEN
    RAISE EXCEPTION 'a % event refers to the fill it records', NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT a.kind::text, a.owner_id, a.market_id INTO from_kind, from_owner, from_market
    FROM ledger_accounts a WHERE a.id = NEW.from_account_id;
  SELECT a.kind::text, a.owner_id, a.market_id INTO to_kind, to_owner, to_market
    FROM ledger_accounts a WHERE a.id = NEW.to_account_id;
  IF NEW.type::text = 'TRADE_FILL' THEN
    payer := CASE f.side WHEN 'buy' THEN f.incoming_owner_id ELSE f.resting_owner_id END;
    payee := CASE f.side WHEN 'buy' THEN f.resting_owner_id ELSE f.incoming_owner_id END;
    IF coalesce(f.kind <> 'trade' OR NEW.market_id IS DISTINCT FROM f.market_id
       OR NEW.idempotency_key <> f.id::text OR NEW.amount_coin <> f.amount_coin
       OR from_owner IS DISTINCT FROM payer OR to_owner IS DISTINCT FROM payee
       OR NOT (from_kind = 'user' OR (from_kind = 'market_maker_funds' AND from_market = f.market_id))
       OR NOT (to_kind = 'user' OR (to_kind = 'market_maker_funds' AND to_market = f.market_id)),
       true) THEN
      RAISE EXCEPTION 'a TRADE_FILL moves fill %''s amount from its buyer to its seller', f.id
        USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
    END IF;
  ELSE
    leg := substr(NEW.idempotency_key, length(f.id::text) + 2);
    payer := CASE WHEN (leg = 'YES') = (f.outcome = 'YES') THEN f.incoming_owner_id
                  ELSE f.resting_owner_id END;
    amount := CASE leg WHEN 'YES' THEN f.yes_price_coin ELSE 100 - f.yes_price_coin END
              * f.qty::bigint;
    IF coalesce(f.kind <> 'pair_mint' OR leg NOT IN ('YES', 'NO')
       OR NEW.idempotency_key <> f.id::text || ':' || leg OR NEW.amount_coin <> amount
       OR from_owner IS DISTINCT FROM payer
       OR NOT (from_kind = 'user' OR (from_kind = 'market_maker_funds' AND from_market = f.market_id))
       OR to_kind IS DISTINCT FROM 'market_collateral' OR to_market IS DISTINCT FROM f.market_id,
       true) THEN
      RAISE EXCEPTION 'a PAIR_MINT_COLLATERAL moves one buyer''s leg of fill % into its collateral',
        f.id
        USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER ledger_entries_fill_binding
  BEFORE INSERT ON "ledger_entries"
  FOR EACH ROW
  WHEN (NEW.type IN ('TRADE_FILL', 'PAIR_MINT_COLLATERAL'))
  EXECUTE FUNCTION ledger_entries_fill_binding();--> statement-breakpoint
-- Hand-edited: a market's 가격 보호 폭 is fixed from its review on (ADR-0093 #172 6항, ADR-0107 결정 1
-- #177 2항), whoever writes. It changes while the market is a draft — at its creation's copy, an
-- edit, and the review submission that fills it in the UPDATE that moves it to REVIEW — and after
-- the open only by the after-open change of an OPEN or PAUSED market, which keeps the status; a
-- value is never cleared. A 반려 or a 되돌리기 keeps it.
CREATE FUNCTION markets_price_protection_fixed() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.price_protection_ticks IS DISTINCT FROM OLD.price_protection_ticks
     AND (NEW.price_protection_ticks IS NULL
          OR NOT (OLD.status = 'draft'
                  OR (OLD.status IN ('open', 'paused') AND NEW.status = OLD.status))) THEN
    RAISE EXCEPTION 'market %''s price protection width is fixed from its review on', OLD.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER markets_price_protection_fixed
  BEFORE UPDATE OF price_protection_ticks ON "markets"
  FOR EACH ROW EXECUTE FUNCTION markets_price_protection_fixed();